"""Trust fixes: a spent embedding quota pauses ingestion instead of failing files (G1), generated / minified
files are skipped (G6), files containing credentials are skipped and reported (G7)."""
import uuid
from datetime import datetime, timezone

import pytest
from sqlalchemy import select

from app.ingestion import safety, worker
from app.models import File, Project
from app.providers.embeddings import EmbeddingQuotaError, get_embedding_provider

GOOD = "def validate_token(token):\n    return decode(token)\n"


async def _upload(client, items):
    pid = (await client.post("/projects", json={"name": "T"})).json()["id"]
    res = await client.post(
        f"/projects/{pid}/upload", files=[("files", (p, d if isinstance(d, bytes) else d.encode())) for p, d in items],
        data={"paths": [p for p, _ in items]},
    )
    assert res.status_code == 200, res.text
    return pid, res.json()


@pytest.fixture(autouse=True)
def _clean_worker_state():
    yield
    worker._paused.clear()
    for handle in worker._resume_handles.values():
        handle.cancel()
    worker._resume_handles.clear()


# --- G1: quota ---
async def test_a_spent_quota_pauses_the_job_and_keeps_files_pending(client, ingest, sessions, monkeypatch):
    pid, _ = await _upload(client, [("a.py", GOOD), ("b.py", "def other():\n    return 2\n")])
    provider = get_embedding_provider()

    async def exhausted(texts):
        raise EmbeddingQuotaError("HTTP 429 quota", daily=True)

    monkeypatch.setattr(provider, "embed_documents", exhausted)
    await ingest(pid)

    async with sessions() as s:
        statuses = {f.file_path: (f.status, f.error_message) for f in (await s.scalars(select(File))).all()}
        project = await s.get(Project, uuid.UUID(pid))
    assert statuses == {"a.py": ("pending", None), "b.py": ("pending", None)}  # nothing failed, nothing is red
    assert project.status == "processing"
    until, daily = worker.paused_until(uuid.UUID(pid))
    assert daily is True and until > datetime.now(timezone.utc)

    out = (await client.get(f"/projects/{pid}")).json()
    assert out["paused_until"] is not None and out["paused_daily_quota"] is True


async def test_the_paused_job_finishes_when_the_quota_is_back(client, ingest, sessions, monkeypatch):
    pid, _ = await _upload(client, [("a.py", GOOD)])
    provider = get_embedding_provider()
    real = provider.embed_documents

    async def exhausted(texts):
        raise EmbeddingQuotaError("HTTP 429 quota")

    monkeypatch.setattr(provider, "embed_documents", exhausted)
    await ingest(pid)
    assert worker.paused_until(uuid.UUID(pid)) is not None

    monkeypatch.setattr(provider, "embed_documents", real)  # the quota came back; the timer would re-queue
    await ingest(pid)
    async with sessions() as s:
        assert [f.status for f in (await s.scalars(select(File))).all()] == ["ready"]
        assert (await s.get(Project, uuid.UUID(pid))).status == "ready"
    assert worker.paused_until(uuid.UUID(pid)) is None
    assert (await client.get(f"/projects/{pid}")).json()["paused_until"] is None


async def test_other_embedding_errors_still_fail_only_that_file(client, ingest, sessions, monkeypatch):
    from app.providers.embeddings import EmbeddingError

    pid, _ = await _upload(client, [("a.py", GOOD)])

    async def broken(texts):
        raise EmbeddingError("HTTP 400 bad request")

    monkeypatch.setattr(get_embedding_provider(), "embed_documents", broken)
    await ingest(pid)
    async with sessions() as s:
        assert [f.status for f in (await s.scalars(select(File))).all()] == ["failed"]
    assert worker.paused_until(uuid.UUID(pid)) is None


# --- G6: generated files ---
def test_minified_and_generated_source_is_detected():
    assert safety.looks_generated(b"var a=1;" * 2000, "source")  # one 16,000-character line
    assert safety.looks_generated(b"function f(){}\n//# sourceMappingURL=app.js.map\n", "source")
    assert safety.looks_generated(b"// Code generated by protoc. DO NOT EDIT.\npackage x\n", "source")
    assert not safety.looks_generated(GOOD.encode(), "source")
    assert not safety.looks_generated(b'{"a":' + b"1," * 5000 + b'0}', "other")  # a long JSON data line is fine


async def test_generated_files_are_skipped_with_a_reason(client):
    pid, report = await _upload(client, [
        ("src/app.py", GOOD),
        ("dist-ish/app.min.js", "var a=1;"),
        ("web/bundle.js", "x=1;" * 3000),
        ("web/footer.js", "function f(){}\n//# sourceMappingURL=footer.js.map\n"),
        ("yarn.lock", "# yarn lockfile"),
        ("Cargo.lock", "[[package]]"),
    ])
    reasons = {r["path"]: r["reason"] for r in report["results"] if r["status"] == "rejected"}
    assert reasons == {
        "dist-ish/app.min.js": "generated_file", "web/bundle.js": "generated_file",
        "web/footer.js": "generated_file", "yarn.lock": "ignored", "Cargo.lock": "ignored",
    }
    assert report["created"] == ["src/app.py"]


# --- G7: secrets ---
@pytest.mark.parametrize("label,content", [
    ("a private key", "-----BEGIN RSA PRIVATE KEY-----\nMIIE\n-----END RSA PRIVATE KEY-----\n"),
    ("an AWS access key", "AWS_KEY = 'AKIAABCDEFGHIJKLMNOP'\n"),
    ("a GitHub token", "token = 'ghp_" + "a" * 36 + "'\n"),
    ("a Groq API key", "key = 'gsk_" + "b" * 52 + "'\n"),
    ("a Google API key", "key = 'AIza" + "c" * 35 + "'\n"),
    ("a Slack token", "t = 'xoxb-1234567890-abcdefghij'\n"),
    ("a Stripe live key", "k = 'sk_live_" + "d" * 24 + "'\n"),
])
def test_secret_patterns_are_found(label, content):
    assert safety.find_secret("config.py", content.encode(), "source") == label


def test_ordinary_text_and_placeholders_are_not_flagged():
    for text in ("password = get_password()\n", "api_key = os.getenv('API_KEY')\n", "Use sk-... as the key\n",
                 "AKIA is the prefix of AWS keys\n", "# set GROQ_API_KEY in .env\n"):
        assert safety.find_secret("a.py", text.encode(), "source") is None, text
    assert safety.find_secret("manual.pdf", b"-----BEGIN PRIVATE KEY-----", "doc") is None  # binary formats are not scanned


def test_credential_files_are_flagged_by_name():
    assert safety.secret_by_name("deploy/credentials.json") == "a credentials file"
    assert safety.secret_by_name("keys/server.pem") == "a credentials file"
    assert safety.secret_by_name(".env.production") == "an environment file"
    assert safety.secret_by_name(".env.example") is None


async def test_files_with_credentials_are_skipped_and_reported_without_echoing_the_secret(client, sessions):
    pid, report = await _upload(client, [
        ("ok.py", GOOD),
        ("settings.py", "AWS = 'AKIAABCDEFGHIJKLMNOP'\n"),
        ("credentials.json", '{"a": 1}'),
    ])
    rejected = {r["path"]: r for r in report["results"] if r["status"] == "rejected"}
    assert rejected["settings.py"]["reason"] == "possible_secret"
    assert rejected["settings.py"]["detail"] == "looks like an AWS access key"
    assert "AKIA" not in str(report)
    assert rejected["credentials.json"]["reason"] == "possible_secret"
    assert report["created"] == ["ok.py"] and report["accepted"] == 1 and report["rejected"] == 2
    async with sessions() as s:
        assert [f.file_path for f in (await s.scalars(select(File))).all()] == ["ok.py"]  # never stored


async def test_replacing_a_file_with_one_that_contains_a_secret_is_refused(client, ingest):
    pid, _ = await _upload(client, [("ok.py", GOOD)])
    await ingest(pid)
    fid = (await client.get(f"/projects/{pid}/files")).json()[0]["id"]
    res = await client.put(f"/files/{fid}", files={"file": ("ok.py", b"k = 'AKIAABCDEFGHIJKLMNOP'\n")})
    assert res.status_code == 422
    assert (await client.get(f"/files/{fid}/content")).text == GOOD  # the stored version is untouched
